\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\pagestyle{empty} %% IMPORTANT
\begin{tikzpicture}

	\begin{axis}[
	legend cell align={left},
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend pos=outer north east,
	legend style={font=\footnotesize},
	tick style={draw=black},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	axis equal,
	%grid = both,
	xmin = -1.5,
	xmax = 2.5,
	ymin = -0.5,
	ymax = 3.5,
	xtick = {1},
	ytick = {1,2.71},
	%xticklabels = {$\pi/4$},
	yticklabels = {$1$,$e$},
	xlabel = {$y$},
	ylabel = {$z$},
%yticklabel style={right, xshift=3pt},
%% Here, we can control the positioning of each individual tick.
%x tick label style={xshift={(\tick==2)*-2pt}},
	xlabel style={below right},
	ylabel style={above left},
	every axis x label/.style={
	at={(ticklabel* cs:1.02)},anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

%% Fill
\draw[draw=none,fill=orangepeel!30, fill opacity=0.5] plot [domain=0:1,samples=200,variable=\x] (axis cs: {\x},{exp(\x)}) --
(axis cs: {1}, {2.71}) -- (axis cs: {1}, {1}) -- cycle;

% 1
\addplot [domain=-3:3,samples=500,color=orangepeel,line width=1pt,dotted,opacity=0.5] ({\x},{exp(\x))});
\addplot [domain=0:1,samples=500,color=orangepeel,line width=1pt] ({\x},{exp(\x))});;

\node[orangepeel, below right] at (axis cs:0.15,3.32) {$\small y = \ln{z}$};

\draw[dashed, ultra thin] (axis cs:0,2.71) -- (axis cs:1,2.71) ;
\draw[dashed, ultra thin] (axis cs:1,0) -- (axis cs:1,1) -- (axis cs:0,1) ;

%Sides
\draw[deepskyblue, line width= 1pt] (axis cs:1,1) -- (axis cs:1,2.71);
\node[deepskyblue, right] at (axis cs:1,1.5) {$y = 1$};

\node[orangepeel] at (axis cs: 0.65,1.4) {$D$};
\draw[->, black, thick] (axis cs:0.4,2.0) -- (axis cs:1.25,2.0);

\end{axis}
\end{tikzpicture}
